import EmblaCarousel from 'embla-carousel';

function createThumbsMarkup(emblaNode) {
    const mainSlides = emblaNode.querySelectorAll('.embla__slide');

    const thumbsNode = document.createElement('div');

    thumbsNode.className = 'embla-thumbs';
    thumbsNode.setAttribute('data-carousel-thumbs', '');
    thumbsNode.setAttribute('data-carousel-generated-thumbs', '');

    thumbsNode.innerHTML = `
        <div class="embla-thumbs__viewport">
            <div class="embla-thumbs__container"></div>
        </div>
    `;

    const thumbsContainer = thumbsNode.querySelector(
        '.embla-thumbs__container'
    );

    mainSlides.forEach((slide, index) => {
        const thumbSrc = slide.dataset.carouselThumbSrc;

        const thumbButton = document.createElement('button');

        thumbButton.type = 'button';
        thumbButton.className = 'embla-thumbs__slide';

        thumbButton.setAttribute('aria-label', `Go to slide ${index + 1}`);

        if (thumbSrc) {
            const image = document.createElement('img');

            image.src = thumbSrc;
            image.alt = '';

            thumbButton.appendChild(image);
        }

        thumbsContainer.appendChild(thumbButton);
    });

    emblaNode.insertAdjacentElement('afterend', thumbsNode);

    return thumbsNode;
}

function addThumbBehaviour(emblaApiMain, emblaApiThumb) {
    const thumbSlides = emblaApiThumb.slideNodes();

    const clickHandlers = thumbSlides.map((_, index) => () => {
        emblaApiMain.scrollTo(index);
    });

    const updateSelectedThumb = () => {
        const selectedIndex = emblaApiMain.selectedScrollSnap();

        emblaApiThumb.scrollTo(selectedIndex);

        thumbSlides.forEach((thumbSlide, index) => {
            const isSelected = index === selectedIndex;

            thumbSlide.classList.toggle(
                'embla-thumbs__slide--selected',
                isSelected
            );

            if (isSelected) {
                thumbSlide.setAttribute('aria-current', 'true');
            } else {
                thumbSlide.removeAttribute('aria-current');
            }
        });
    };

    thumbSlides.forEach((thumbSlide, index) => {
        thumbSlide.addEventListener('click', clickHandlers[index]);
    });

    emblaApiMain
        .on('select', updateSelectedThumb)
        .on('reInit', updateSelectedThumb);

    updateSelectedThumb();

    return () => {
        thumbSlides.forEach((thumbSlide, index) => {
            thumbSlide.removeEventListener('click', clickHandlers[index]);

            thumbSlide.classList.remove('embla-thumbs__slide--selected');

            thumbSlide.removeAttribute('aria-current');
        });
    };
}

export function setupThumbs(emblaNode, emblaApiMain, options = {}) {
    const { create = false } = options;

    const carouselContainer = emblaNode.closest('[data-carousel-container]');

    /*
     * Existing thumbs should normally be inside the shared
     * data-carousel-container wrapper.
     */
    let thumbsNode = null;

    if (carouselContainer) {
        thumbsNode = carouselContainer.querySelector('[data-carousel-thumbs]');
    }

    let generatedThumbs = false;

    if (!thumbsNode && create) {
        thumbsNode = createThumbsMarkup(emblaNode);
        generatedThumbs = true;
    }

    if (!thumbsNode) {
        return () => {};
    }

    const thumbsViewport = thumbsNode.querySelector('.embla-thumbs__viewport');

    if (!thumbsViewport) {
        return () => {};
    }

    const emblaApiThumb = EmblaCarousel(thumbsViewport, {
        containScroll: 'keepSnaps',
        dragFree: true,
    });

    const removeThumbBehaviour = addThumbBehaviour(emblaApiMain, emblaApiThumb);

    return () => {
        removeThumbBehaviour();
        emblaApiThumb.destroy();

        if (generatedThumbs) {
            thumbsNode.remove();
        }
    };
}
